head.script:
// 결함 재현 시나리오 설명
scwin.tData = {
    "description" : "[FAIL] accordion 컴포넌트의 setDisabled(true) / setReadOnly(true) 호출 후에도 panelTitle 클릭으로 패널이 토글되고 onclick / onpanelload / onpanelunload 이벤트가 발생하는 결함 재현",
    "validation" : [
        "setDisabled(true) 호출 후 가이드 @spec : 컴포넌트에 대한 입력, 포커스, 이벤트 등이 차단되어야 합니다.",
        "setReadOnly(true) 호출 후 가이드 @spec : 입력 및 편집이 차단되어야 합니다.",
        "실제 동작 : setDisabled / setReadOnly true 설정 후에도 panelTitle 클릭으로 패널이 열림/닫힘 토글되고 onclick / onpanelload / onpanelunload 이벤트가 모두 발생합니다 (options 값만 저장될 뿐 동작 차단/UI 반영 없음)."
    ]
}



scwin.onpageload = function () {

};



// setDisabled(true)
scwin.btn_setDisabledTrue_onclick = function (e) {
    target_accordion.setDisabled(true);
    scwin.setReturnValue("[setDisabled(true) 호출] getDisabled() = " + target_accordion.getDisabled());
};

// setDisabled(false)
scwin.btn_setDisabledFalse_onclick = function (e) {
    target_accordion.setDisabled(false);
    scwin.setReturnValue("[setDisabled(false) 호출] getDisabled() = " + target_accordion.getDisabled());
};

// setReadOnly(true)
scwin.btn_setReadOnlyTrue_onclick = function (e) {
    target_accordion.setReadOnly(true);
    scwin.setReturnValue("[setReadOnly(true) 호출] getReadOnly() = " + target_accordion.getReadOnly());
};

// setReadOnly(false)
scwin.btn_setReadOnlyFalse_onclick = function (e) {
    target_accordion.setReadOnly(false);
    scwin.setReturnValue("[setReadOnly(false) 호출] getReadOnly() = " + target_accordion.getReadOnly());
};



// target_accordion 이벤트 핸들러 (차단 여부 확인용)
scwin.target_accordion_onclick = function (panel, open) {
    scwin.setReturnValue("=====target_accordion_onclick===== (disabled : " + target_accordion.getDisabled() + " / readOnly : " + target_accordion.getReadOnly() + ")");
    scwin.setReturnValue("panel.id : " + (panel ? panel.id : "null") + " / open : " + open);
};

scwin.target_accordion_onpanelload = function (panelID, userID) {
    scwin.setReturnValue("=====target_accordion_onpanelload===== panelID : " + panelID);
};

scwin.target_accordion_onpanelunload = function (panelID, userID) {
    scwin.setReturnValue("=====target_accordion_onpanelunload===== panelID : " + panelID);
};



// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정 (독립 실행용)
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
